// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetApiInfo Service metadata
	// (GET /api)
	GetApiInfo(ctx context.Context, request GetApiInfoRequestObject) (GetApiInfoResponseObject, error)
	// ListEvents Events of the current organization, newest first
	// (GET /api/organization/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// CreateEvent Create a draft event; no credit is used
	// (POST /api/organization/events)
	CreateEvent(ctx context.Context, request CreateEventRequestObject) (CreateEventResponseObject, error)
	// GetEvent Event detail
	// (GET /api/organization/events/{eventId})
	GetEvent(ctx context.Context, request GetEventRequestObject) (GetEventResponseObject, error)
	// UpdateEvent Change settings or status; the first move to ready uses one credit
	// (PATCH /api/organization/events/{eventId})
	UpdateEvent(ctx context.Context, request UpdateEventRequestObject) (UpdateEventResponseObject, error)
	// ListAttendees Roster, in the order it was added
	// (GET /api/organization/events/{eventId}/attendees)
	ListAttendees(ctx context.Context, request ListAttendeesRequestObject) (ListAttendeesResponseObject, error)
	// CreateAttendee Add one person
	// (POST /api/organization/events/{eventId}/attendees)
	CreateAttendee(ctx context.Context, request CreateAttendeeRequestObject) (CreateAttendeeResponseObject, error)
	// DeleteAttendee Remove a person who has not bound, checked in or won
	// (DELETE /api/organization/events/{eventId}/attendees/{attendeeId})
	DeleteAttendee(ctx context.Context, request DeleteAttendeeRequestObject) (DeleteAttendeeResponseObject, error)
	// UpdateAttendee Change name, department or phone
	// (PATCH /api/organization/events/{eventId}/attendees/{attendeeId})
	UpdateAttendee(ctx context.Context, request UpdateAttendeeRequestObject) (UpdateAttendeeResponseObject, error)
	// GetEventEntry Public code and mini program path
	// (GET /api/organization/events/{eventId}/entry)
	GetEventEntry(ctx context.Context, request GetEventEntryRequestObject) (GetEventEntryResponseObject, error)
	// ListPrizes Prizes by sort_no
	// (GET /api/organization/events/{eventId}/prizes)
	ListPrizes(ctx context.Context, request ListPrizesRequestObject) (ListPrizesResponseObject, error)
	// CreatePrize Add a prize
	// (POST /api/organization/events/{eventId}/prizes)
	CreatePrize(ctx context.Context, request CreatePrizeRequestObject) (CreatePrizeResponseObject, error)
	// DeletePrize Delete a prize
	// (DELETE /api/organization/events/{eventId}/prizes/{prizeId})
	DeletePrize(ctx context.Context, request DeletePrizeRequestObject) (DeletePrizeResponseObject, error)
	// UpdatePrize Change a prize
	// (PATCH /api/organization/events/{eventId}/prizes/{prizeId})
	UpdatePrize(ctx context.Context, request UpdatePrizeRequestObject) (UpdatePrizeResponseObject, error)
	// OrganizationLogin Organization admin login
	// (POST /api/organization/login)
	OrganizationLogin(ctx context.Context, request OrganizationLoginRequestObject) (OrganizationLoginResponseObject, error)
	// OrganizationLogout Revoke the current console token
	// (POST /api/organization/logout)
	OrganizationLogout(ctx context.Context, request OrganizationLogoutRequestObject) (OrganizationLogoutResponseObject, error)
	// GetOrganizationMe Current admin and its organization
	// (GET /api/organization/me)
	GetOrganizationMe(ctx context.Context, request GetOrganizationMeRequestObject) (GetOrganizationMeResponseObject, error)
	// ChangeOrganizationPassword Change the admin password
	// (POST /api/organization/password)
	ChangeOrganizationPassword(ctx context.Context, request ChangeOrganizationPasswordRequestObject) (ChangeOrganizationPasswordResponseObject, error)
	// PlatformLogin Platform operator login
	// (POST /api/platform/login)
	PlatformLogin(ctx context.Context, request PlatformLoginRequestObject) (PlatformLoginResponseObject, error)
	// PlatformLogout Revoke the current platform token
	// (POST /api/platform/logout)
	PlatformLogout(ctx context.Context, request PlatformLogoutRequestObject) (PlatformLogoutResponseObject, error)
	// GetPlatformMe Current platform operator
	// (GET /api/platform/me)
	GetPlatformMe(ctx context.Context, request GetPlatformMeRequestObject) (GetPlatformMeResponseObject, error)
	// ListOrgs List organizations, newest first
	// (GET /api/platform/orgs)
	ListOrgs(ctx context.Context, request ListOrgsRequestObject) (ListOrgsResponseObject, error)
	// CreateOrg Open an organization with its initial quota
	// (POST /api/platform/orgs)
	CreateOrg(ctx context.Context, request CreateOrgRequestObject) (CreateOrgResponseObject, error)
	// GetOrg Organization, quota and the latest 20 ledger entries
	// (GET /api/platform/orgs/{orgId})
	GetOrg(ctx context.Context, request GetOrgRequestObject) (GetOrgResponseObject, error)
	// AdjustOrgCredits Add or remove event credits with a reason
	// (POST /api/platform/orgs/{orgId}/credits)
	AdjustOrgCredits(ctx context.Context, request AdjustOrgCreditsRequestObject) (AdjustOrgCreditsResponseObject, error)
	// DisableOrg Disable an organization; idempotent
	// (POST /api/platform/orgs/{orgId}/disable)
	DisableOrg(ctx context.Context, request DisableOrgRequestObject) (DisableOrgResponseObject, error)
	// EnableOrg Enable an organization; idempotent
	// (POST /api/platform/orgs/{orgId}/enable)
	EnableOrg(ctx context.Context, request EnableOrgRequestObject) (EnableOrgResponseObject, error)
	// SetOrgMaxAttendees Change the default attendee limit for events created afterwards
	// (POST /api/platform/orgs/{orgId}/max-attendees)
	SetOrgMaxAttendees(ctx context.Context, request SetOrgMaxAttendeesRequestObject) (SetOrgMaxAttendeesResponseObject, error)
	// ListOrgUsers Admins of an organization
	// (GET /api/platform/orgs/{orgId}/users)
	ListOrgUsers(ctx context.Context, request ListOrgUsersRequestObject) (ListOrgUsersResponseObject, error)
	// CreateOrgUser Create an admin with a one-time password
	// (POST /api/platform/orgs/{orgId}/users)
	CreateOrgUser(ctx context.Context, request CreateOrgUserRequestObject) (CreateOrgUserResponseObject, error)
	// DisableOrgUser Disable an admin and revoke its tokens; idempotent
	// (POST /api/platform/orgs/{orgId}/users/{userId}/disable)
	DisableOrgUser(ctx context.Context, request DisableOrgUserRequestObject) (DisableOrgUserResponseObject, error)
	// EnableOrgUser Enable an admin without changing its password; idempotent
	// (POST /api/platform/orgs/{orgId}/users/{userId}/enable)
	EnableOrgUser(ctx context.Context, request EnableOrgUserRequestObject) (EnableOrgUserResponseObject, error)
	// ResetOrgUserPassword Replace the password and revoke every token of the admin
	// (POST /api/platform/orgs/{orgId}/users/{userId}/reset-password)
	ResetOrgUserPassword(ctx context.Context, request ResetOrgUserPasswordRequestObject) (ResetOrgUserPasswordResponseObject, error)
	// ChangePlatformPassword Change the platform operator password
	// (POST /api/platform/password)
	ChangePlatformPassword(ctx context.Context, request ChangePlatformPasswordRequestObject) (ChangePlatformPasswordResponseObject, error)
	// GetHealthz Liveness and database ping
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetOpenAPIJSON OpenAPI document (JSON)
	// (GET /openapi.json)
	GetOpenAPIJSON(ctx context.Context, request GetOpenAPIJSONRequestObject) (GetOpenAPIJSONResponseObject, error)
	// GetOpenAPIYaml OpenAPI document (YAML)
	// (GET /openapi.yaml)
	GetOpenAPIYaml(ctx context.Context, request GetOpenAPIYamlRequestObject) (GetOpenAPIYamlResponseObject, error)
}

